long long C(long long n, long long k, long long mod) {
    if (k < 0 || k > n) return 0;
    long long num = 1, den = 1;
    for (long long i = 0; i < k; i++) {
        num = num * ((n - i) % mod) % mod;
        den = den * ((i + 1) % mod) % mod;
    }
    return num % mod * inv(den, mod) % mod;
}

