#define MOD 1000000007LL

static long long mod_pow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    long long N, M, K;
    if (scanf("%lld %lld %lld", &N, &M, &K) != 3) return 0;

    long long cells = N * M;

    if (K < 2 || K > cells) {
        printf("0\n");
        return 0;
    }

    /* Precompute factorials and inverse factorials up to N*M */
    long long *fact = (long long *)malloc((cells + 1) * sizeof(long long));
    long long *invfact = (long long *)malloc((cells + 1) * sizeof(long long));
    if (!fact || !invfact) return 0;

    fact[0] = 1;
    for (long long i = 1; i <= cells; i++) {
        fact[i] = fact[i - 1] * i % MOD;
    }

    invfact[cells] = mod_pow(fact[cells], MOD - 2);
    for (long long i = cells; i >= 1; i--) {
        invfact[i - 1] = invfact[i] * i % MOD;
    }

    long long comb = fact[cells - 2];
    comb = comb * invfact[K - 2] % MOD;
    comb = comb * invfact[cells - K] % MOD;

    /* 
       Sum over all unordered pairs of cells of Manhattan distance:
       row contribution:
         M^2 * sum_{1<=a<b<=N} (b-a)
       col contribution:
         N^2 * sum_{1<=a<b<=M} (b-a)

       And:
         sum_{1<=a<b<=X} (b-a) = X(X-1)(X+1)/6
    */
    long long inv6 = mod_pow(6, MOD - 2);

    long long n_mod = N % MOD;
    long long m_mod = M % MOD;

    long long rowPairs = n_mod * ((N - 1) % MOD) % MOD * ((N + 1) % MOD) % MOD * inv6 % MOD;
    long long colPairs = m_mod * ((M - 1) % MOD) % MOD * ((M + 1) % MOD) % MOD * inv6 % MOD;

    long long rowContribution = (m_mod * m_mod) % MOD * rowPairs % MOD;
    long long colContribution = (n_mod * n_mod) % MOD * colPairs % MOD;

    long long pairDistanceSum = (rowContribution + colContribution) % MOD;

    long long ans = pairDistanceSum * comb % MOD;
    printf("%lld\n", ans);

    free(fact);
    free(invfact);
    return 0;
}

