public class Main {
    static final long MOD = 1_000_000_007L;

    static long modPow(long a, long e) {
        long r = 1;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static long comb(long n, long r, long[] fact, long[] invFact) {
        if (r < 0 || r > n) return 0;
        return fact[(int)n] * invFact[(int)r] % MOD * invFact[(int)(n - r)] % MOD;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();
        int K = fs.nextInt();

        long cells = 1L * N * M;
        if (K < 2 || K > cells) {
            System.out.println(0);
            return;
        }

        int max = (int) cells;
        long[] fact = new long[max + 1];
        long[] invFact = new long[max + 1];
        fact[0] = 1;
        for (int i = 1; i <= max; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[max] = modPow(fact[max], MOD - 2);
        for (int i = max; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long pairWays = comb(cells - 2, K - 2, fact, invFact);

        long rowSum = 0;
        for (int d = 1; d < N; d++) {
            long cnt = (long) (N - d) * M % MOD * M % MOD;
            rowSum = (rowSum + cnt * d) % MOD;
        }

        long colSum = 0;
        for (int d = 1; d < M; d++) {
            long cnt = (long) (M - d) * N % MOD * N % MOD;
            colSum = (colSum + cnt * d) % MOD;
        }

        long totalPairDistance = (rowSum + colSum) % MOD;
        long ans = totalPairDistance * pairWays % MOD;
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

