    long long cells = N * M;

    if (K < 2 || K > cells) {
        cout << 0 << '\n';
        return 0;
    }

    // Sum of Manhattan distances over all unordered pairs of cells.
    // Row contribution:
    // M^2 * sum_{1<=a<b<=N} (b-a)
    // and sum_{1<=a<b<=N} (b-a) = N(N-1)(N+1)/6
    long long inv6 = modpow(6, MOD - 2);

    long long n = N % MOD;
    long long m = M % MOD;

    long long rowSum = n * ((N - 1) % MOD) % MOD * ((N + 1) % MOD) % MOD * inv6 % MOD;
    long long colSum = m * ((M - 1) % MOD) % MOD * ((M + 1) % MOD) % MOD * inv6 % MOD;

    long long totalPairDist = 0;
    totalPairDist += (m * m % MOD) * rowSum % MOD;
    totalPairDist %= MOD;
    totalPairDist += (n * n % MOD) * colSum % MOD;
    totalPairDist %= MOD;

    // Each unordered pair of cells appears in exactly C(NM-2, K-2) arrangements.
    long long maxN = cells;
    vector<long long> fact(maxN + 1), invfact(maxN + 1);
