    auto C = [&](long long a, long long b) -> long long {
        if (b < 0 || b > a) return 0;
        return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD;
    };

    long long ways = C(cells - 2, K - 2);
    long long ans = totalPairDist * ways % MOD;

    cout << ans << '\n';
    return 0;
